mapper.select:
SELECT sub.ID id, sub.SUBJECT_NAME subjectName, sub.SUBJECT_URL subjectUrl,
sub.CREATE_TIME createTime, sub.UPDATE_TIME updateTime, sub.SUBJECT_ORDER subjectOrder
FROM APP_SUBJECT sub LEFT JOIN APP_PARK_SUBJECT PS ON PS.SUBJECT_ID = sub.ID
WHERE sub.CATALOG_CODE = #{catalogCode}
AND sub.PUBLISH_FLAG = #{publishFlag}
AND sub.DEL_FLAG = '1'

	AND PS.PARK_ID = #{parkId}

ORDER BY sub.SUBJECT_ORDER ASC, sub.CREATE_TIME  DESC

SELECT sub.ID id, sub.SUBJECT_NAME subjectName, sub.SUBJECT_URL subjectUrl,
sub.CREATE_TIME createTime, sub.UPDATE_TIME updateTime, sub.SUBJECT_ORDER subjectOrder
FROM APP_SUBJECT sub LEFT JOIN APP_PARK_SUBJECT PS ON PS.SUBJECT_ID = sub.ID
WHERE sub.DEL_FLAG = '1'

	AND sub.CATALOG_CODE = #{query.catalogCode}


	AND sub.PUBLISH_FLAG = #{query.publishFlag}


	AND PS.PARK_ID = #{query.parkId}


	AND sub.SUBJECT_NAME like concat(concat('%',#{query.subjectName}),'%')


	and PS.PARK_ID in

		#{item}


ORDER BY sub.SUBJECT_ORDER ASC, sub.CREATE_TIME  DESC

SELECT sub.ID, sub.SUBJECT_NAME, sub.SUBJECT_URL,sub.CREATE_TIME,sct.CONTENT_TEXT_ID
FROM APP_SUBJECT sub
LEFT JOIN APP_PARK_SUBJECT PS ON PS.SUBJECT_ID = sub."ID"
left JOIN APP_SUBJECT_CONTENT_TEXT sct ON sub.ID=sct.SUBJECT_ID
WHERE sub.DEL_FLAG = '1'

	AND sub.CATALOG_CODE = #{query.catalogCode}


	AND sub.PUBLISH_FLAG = #{query.publishFlag}


	AND PS.PARK_ID = #{query.parkId}


	and PS.PARK_ID in

		#{item}


ORDER BY sub.CREATE_TIME  DESC

SELECT SUBJECT_ORDER
FROM APP_SUBJECT
WHERE ID = #{id}

SELECT ID
FROM APP_SUBJECT
WHERE SUBJECT_ORDER = #{order}
AND CATALOG_CODE =  #{catalogCode}

mapper.update:
UPDATE APP_SUBJECT SET SUBJECT_ORDER = SUBJECT_ORDER ${operate}
WHERE CATALOG_CODE = #{catalogCode}
AND SUBJECT_ORDER BETWEEN #{frist} AND #{last}

mapper.select:
SELECT CONTENT_TEXT_ID
FROM APP_SUBJECT_CONTENT_TEXT
WHERE SUBJECT_ID = #{subjectId}

select subject.ID,subject.SUBJECT_NAME,subject.CREATE_TIME from APP_SUBJECT subject left join APP_SUBJECT_CONTENT_TEXT asct on subject.ID=asct.SUBJECT_ID left join APP_CONTENT_TEXT act on asct.CONTENT_TEXT_ID=act.ID where subject.del_flag = '1'
and subject.SUBJECT_NAME LIKE #{query.subjectName}
and subject.CREATE_TIME >= to_date(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
and subject.CREATE_TIME <= to_date(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
and subject.CATALOG_CODE = #{query.catalogCode}
order by subject.UPDATE_TIME desc
